CREATE OR REPLACE FUNCTION public.admin_set_organizer_status(p_player_id uuid, p_group_id uuid, p_is_organizer boolean, p_order integer DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $$ DECLARE v_admin uuid := auth.uid(); BEGIN IF v_admin IS NULL OR NOT public.has_role(v_admin, 'admin') THEN RAISE EXCEPTION 'not_authorized'; END IF; IF p_is_organizer THEN INSERT INTO public.player_groups (player_id, group_id, status, is_organizer, organizer_order) VALUES (p_player_id, p_group_id, 'approved', true, COALESCE(p_order, 99)) ON CONFLICT (player_id, group_id) DO UPDATE SET is_organizer = true, organizer_order = COALESCE(p_order, player_groups.organizer_order, 99), status = 'approved'; ELSE UPDATE public.player_groups SET is_organizer = false, organizer_order = NULL WHERE player_id = p_player_id AND group_id = p_group_id; END IF; INSERT INTO public.admin_actions_log (admin_user_id, action, target_type, target_id, details) VALUES (v_admin, 'set_organizer_status', 'player', p_player_id, jsonb_build_object('group_id', p_group_id, 'is_organizer', p_is_organizer, 'order', p_order)); END; $$;
